// Friendly label for printing tight category
static const char* tightTagName(RecoilJets::TightTag t)
{
switch (t) {
  case RecoilJets::TightTag::kPreselectionFail: return "PreselectionFail";
  case RecoilJets::TightTag::kTight:            return "Tight";
  case RecoilJets::TightTag::kNonTight:         return "NonTight(>=2)";
  case RecoilJets::TightTag::kNeither:          return "Neither(1 fail)";
  default:                                      return "UNKNOWN";
}
}

static std::string recoilJetsLowerCopy(std::string s)
{
std::transform(s.begin(), s.end(), s.begin(),
               [](unsigned char c){ return static_cast<char>(std::tolower(c)); });
return s;
}

static int embeddedPhotonSampleCodeFromText(const std::string& text)
{
const std::string s = recoilJetsLowerCopy(text);

if (s.find("photonjet12") != std::string::npos ||
    s.find("embeddedphoton12") != std::string::npos ||
    s.find("photon12") != std::string::npos)
{
  return 12;
}

if (s.find("photonjet20") != std::string::npos ||
    s.find("embeddedphoton20") != std::string::npos ||
    s.find("photon20") != std::string::npos)
{
  return 20;
}

return 0;
}

static int embeddedPhotonSampleCodeFromContext(const std::string& outFile)
{
if (const char* env = std::getenv("RJ_EMBEDDED_PHOTON_SAMPLE"))
{
  const int fromEnv = embeddedPhotonSampleCodeFromText(env);
  if (fromEnv == 12 || fromEnv == 20) return fromEnv;
}

return embeddedPhotonSampleCodeFromText(outFile);
}

static int embeddedInclusiveJetSampleCodeFromText(const std::string& text)
{
const std::string s = recoilJetsLowerCopy(text);

// Keep the inclusive-jet parser intentionally narrower than the photon parser:
// "PhotonJet12" also contains "jet12", but it is not an inclusive Jet12 sample.
if (s.find("photon") != std::string::npos) return 0;

if (s.find("embeddedjet12") != std::string::npos ||
    s.find("run28_embeddedjet12") != std::string::npos)
{
  return 12;
}

if (s.find("embeddedjet20") != std::string::npos ||
    s.find("run28_embeddedjet20") != std::string::npos)
{
  return 20;
}

if (s.find("embeddedjet30") != std::string::npos ||
    s.find("run28_embeddedjet30") != std::string::npos)
{
  return 30;
}

if (s.find("embeddedjet40") != std::string::npos ||
    s.find("run28_embeddedjet40") != std::string::npos)
{
  return 40;
}

return 0;
}

static bool embeddedInclusiveFourSampleMode()
{
const char* four = std::getenv("RJ_SIMEMBEDDEDINCLUSIVE_FOUR_SAMPLES");
const char* jet40 = std::getenv("RJ_SIMEMBEDDEDINCLUSIVE_INCLUDE_JET40");
return (four && std::string(four) == "1") ||
       (jet40 && std::string(jet40) == "1");
}

static bool embeddedInclusiveThreeSampleMode()
{
const char* three = std::getenv("RJ_SIMEMBEDDEDINCLUSIVE_THREE_SAMPLES");
const char* jet30 = std::getenv("RJ_SIMEMBEDDEDINCLUSIVE_INCLUDE_JET30");
return embeddedInclusiveFourSampleMode() ||
       (three && std::string(three) == "1") ||
       (jet30 && std::string(jet30) == "1");
}

static double recoilJetsEnvDouble(const char* name, double fallback)
{
const char* raw = std::getenv(name);
if (!raw || !*raw) return fallback;
char* end = nullptr;
const double value = std::strtod(raw, &end);
if (end == raw || !std::isfinite(value)) return fallback;
return value;
}

static bool recoilJetsEnvFlag(const char* name, bool fallback = false)
{
const char* raw = std::getenv(name);
if (!raw || !*raw) return fallback;
std::string value(raw);
std::transform(value.begin(), value.end(), value.begin(),
               [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
return !(value == "0" || value == "false" || value == "no" || value == "off");
}

struct EmbeddedInclusiveStitchBounds
{
  double jet12Lo = 12.0;
  double jet12Hi = 20.0;
  double jet20Lo = 20.0;
  double jet20Hi = 30.0;
  double jet30Lo = 30.0;
  double jet30Hi = -1.0;
  double jet40Lo = 40.0;
};

static EmbeddedInclusiveStitchBounds embeddedInclusiveStitchBoundsFromEnv()
{
EmbeddedInclusiveStitchBounds b;
b.jet12Lo = recoilJetsEnvDouble("RJ_SIMEMBEDDEDINCLUSIVE_JET12_LO", b.jet12Lo);
b.jet12Hi = recoilJetsEnvDouble("RJ_SIMEMBEDDEDINCLUSIVE_JET12_HI", b.jet12Hi);
b.jet20Lo = recoilJetsEnvDouble("RJ_SIMEMBEDDEDINCLUSIVE_JET20_LO", b.jet20Lo);
b.jet20Hi = recoilJetsEnvDouble("RJ_SIMEMBEDDEDINCLUSIVE_JET20_HI", b.jet20Hi);
b.jet30Lo = recoilJetsEnvDouble("RJ_SIMEMBEDDEDINCLUSIVE_JET30_LO", b.jet30Lo);
b.jet30Hi = recoilJetsEnvDouble("RJ_SIMEMBEDDEDINCLUSIVE_JET30_HI", b.jet30Hi);
b.jet40Lo = recoilJetsEnvDouble("RJ_SIMEMBEDDEDINCLUSIVE_JET40_LO", b.jet40Lo);
return b;
}

struct EmbeddedPhotonStitchBounds
{
  double photon12Lo = 12.0;
  double photon12Hi = 20.0;
  double photon20Lo = 20.0;
  double photon20Hi = -1.0;
};

static EmbeddedPhotonStitchBounds embeddedPhotonStitchBoundsFromEnv()
{
EmbeddedPhotonStitchBounds b;
b.photon12Lo = recoilJetsEnvDouble("RJ_SIMEMBEDDED_PHOTON12_LO", b.photon12Lo);
b.photon12Hi = recoilJetsEnvDouble("RJ_SIMEMBEDDED_PHOTON12_HI", b.photon12Hi);
b.photon20Lo = recoilJetsEnvDouble("RJ_SIMEMBEDDED_PHOTON20_LO", b.photon20Lo);
b.photon20Hi = recoilJetsEnvDouble("RJ_SIMEMBEDDED_PHOTON20_HI", b.photon20Hi);
return b;
}

static int embeddedInclusiveJetSampleCodeFromContext(const std::string& outFile)
{
if (const char* env = std::getenv("RJ_SIM_SAMPLE"))
{
  const int fromEnv = embeddedInclusiveJetSampleCodeFromText(env);
  if (fromEnv == 12 || fromEnv == 20 || fromEnv == 30 || fromEnv == 40) return fromEnv;
}

if (const char* env = std::getenv("RJ_EMBEDDED_INCLUSIVE_JET_SAMPLE"))
{
  const int fromEnv = embeddedInclusiveJetSampleCodeFromText(env);
  if (fromEnv == 12 || fromEnv == 20 || fromEnv == 30 || fromEnv == 40) return fromEnv;
}

return embeddedInclusiveJetSampleCodeFromText(outFile);
}

static double findEmbeddedProducerFilterPhotonPt(PHCompositeNode* topNode)
{
PHHepMCGenEventMap* hepmcmap = findNode::getClass<PHHepMCGenEventMap>(topNode, "PHHepMCGenEventMap");
PHHepMCGenEvent*    hepmc    = nullptr;
HepMC::GenEvent*    evt      = nullptr;

if (hepmcmap)
{
  hepmc = hepmcmap->get(0);
  if (!hepmc) hepmc = hepmcmap->get(1);
  if (!hepmc && !hepmcmap->empty()) hepmc = hepmcmap->begin()->second;
  if (hepmc) evt = hepmc->getEvent();
}

if (!evt) return -1.0;

double maxPt = -1.0;

for (auto it = evt->particles_begin(); it != evt->particles_end(); ++it)
{
  const HepMC::GenParticle* p = *it;
  if (!p) continue;
  if (p->pdg_id() != 22) continue;

  const double pt  = std::hypot(p->momentum().px(), p->momentum().py());
  const double eta = p->momentum().pseudoRapidity();

  if (!std::isfinite(pt) || !std::isfinite(eta) || pt <= 0.0) continue;
  if (eta < -1.5 || eta > 1.5) continue;

  const HepMC::GenVertex* vtx = p->production_vertex();
  if (!vtx) continue;

  bool parentOk = false;
  for (auto inItr = vtx->particles_in_const_begin(); inItr != vtx->particles_in_const_end(); ++inItr)
  {
    const HepMC::GenParticle* parent = *inItr;
    if (!parent) continue;

    const int absParentId = std::abs(parent->pdg_id());
    if (absParentId >= 1 && absParentId <= 22)
    {
      parentOk = true;
      break;
    }
  }

  if (!parentOk) continue;
  if (pt > maxPt) maxPt = pt;
}

return maxPt;
}

static double findEmbeddedInclusiveStitchTruthJetPt(PHCompositeNode* topNode)
{
// Brian's embed_2025 inclusive-jet production applies PHPy8JetTrigger to
// anti-kT R=0.4 generator jets with Jet12/20/30/40 threshold samples.
// Prefer the r04 truth jet container, then fall back to other available truth
// jet radii only for diagnostics/robustness if r04 is absent.
const std::vector<std::string> candidates = {
  "AntiKt_Truth_r04",
  "AntiKt_TruthFromParticles_r04",
  "AntiKt_Truth_r03",
  "AntiKt_TruthFromParticles_r03",
  "AntiKt_Truth_r02",
  "AntiKt_TruthFromParticles_r02"
};

for (const std::string& node : candidates)
{
  JetContainer* jets = findNode::getClass<JetContainer>(topNode, node);
  if (!jets) continue;

  double maxPt = -1.0;
  for (const Jet* jet : *jets)
  {
    if (!jet) continue;
    const double pt = jet->get_pt();
    if (!std::isfinite(pt) || pt <= 0.0) continue;
    if (pt > maxPt) maxPt = pt;
  }

  if (maxPt > 0.0) return maxPt;
}

return -1.0;
}

